from __future__ import annotations

import base64
import gzip
import hashlib
import json

# Deterministic fixture corpus: the 18-case serialized semantic replay used by
# the research record. It is not a fresh execution of the historical issues.
# The archive is regenerated from the checked-in finite corpus constructors with
# UTF-8, sorted keys, two-space indentation, and a trailing newline.
SHA256 = "91d7a7e4d63030f8fcb553acc6e16533956bede227ed8c0983d25cf0777f857b"
_PAYLOAD = """"""


def load() -> list[dict]:
    raw = gzip.decompress(base64.b64decode(_PAYLOAD))
    if hashlib.sha256(raw).hexdigest() != SHA256:
        raise RuntimeError("fixture corpus checksum mismatch")
    data = json.loads(raw)
    if not isinstance(data, list) or len(data) != 18:
        raise RuntimeError("fixture corpus must contain exactly 18 cases")
    return data


if __name__ == "__main__":
    cases = load()
    print(f"cases={len(cases)}")
    print(f"sha256={SHA256}")
